"""Uncertainty audit and structure extraction on a finite abelian group.

Given a function f on G = Z/n_1 x ... x Z/n_r, compute the discrete Fourier
transform, measure the uncertainty product |supp f| * |supp fhat|, decide
extremality, and -- when f is extremal -- recover the hidden algebraic data
(K, a, chi, c) with f = c * psi_chi * 1_{a+K}.
"""

from __future__ import annotations

import cmath
import itertools
from typing import Dict, List, NamedTuple, Optional, Set, Tuple

Elem = Tuple[int, ...]
Group = Tuple[int, ...]
Func = Dict[Elem, complex]

TOL: float = 1e-9


def elements(group: Group) -> List[Elem]:
    """All group elements, lexicographically ordered."""
    return [tuple(t) for t in itertools.product(*(range(n) for n in group))]


def order(group: Group) -> int:
    """The group order |G|."""
    n = 1
    for m in group:
        n *= m
    return n


def sub(group: Group, x: Elem, y: Elem) -> Elem:
    """Group subtraction x - y."""
    return tuple((a - b) % n for a, b, n in zip(x, y, group))


def add(group: Group, x: Elem, y: Elem) -> Elem:
    """Group addition x + y."""
    return tuple((a + b) % n for a, b, n in zip(x, y, group))


def character(group: Group, k: Elem, x: Elem) -> complex:
    """psi_k(x) = exp(2*pi*i * sum_j k_j x_j / n_j)."""
    phase = sum(2.0 * cmath.pi * (kj * xj) / nj for kj, xj, nj in zip(k, x, group))
    return cmath.exp(1j * phase)


def dft(group: Group, f: Func) -> Func:
    """fhat(k) = sum_x conj(psi_k(x)) f(x).  Cost O(|G|^2)."""
    els = elements(group)
    return {
        k: sum(character(group, k, x).conjugate() * f.get(x, 0j) for x in els)
        for k in els
    }


def support(f: Func, tol: float = TOL) -> Set[Elem]:
    """{x : |f(x)| > tol}."""
    return {x for x, v in f.items() if abs(v) > tol}


class Audit(NamedTuple):
    """Result of an uncertainty audit."""

    space_support: int
    freq_support: int
    product: int
    group_order: int
    extremal: bool
    subgroup: Optional[Set[Elem]]
    representative: Optional[Elem]
    character_index: Optional[Elem]
    scalar: Optional[complex]


def audit(group: Group, f: Func) -> Audit:
    """Full uncertainty audit with structure extraction when extremal."""
    n = order(group)
    s = support(f)
    t = support(dft(group, f))
    product = len(s) * len(t)
    extremal = bool(s) and product == n
    if not extremal:
        return Audit(len(s), len(t), product, n, False, None, None, None, None)

    # The subgroup is the difference set of the support (a combinatorial
    # description of an analytically defined object).
    k_sub = {sub(group, x, y) for x in s for y in s}
    a = sorted(s)[0]
    # The phase f(x)/f(a) equals chi(x - a); match against every character.
    for chi in elements(group):
        c = f[a] * character(group, chi, a).conjugate()
        ok = all(
            abs(f.get(x, 0j) - (c * character(group, chi, x) if x in s else 0j)) < 1e-7
            for x in elements(group)
        )
        if ok:
            return Audit(len(s), len(t), product, n, True, k_sub, a, chi, c)
    raise RuntimeError("extremal function with no coset-modulation form")


if __name__ == "__main__":
    G: Group = (12,)
    K = {(0,), (3,), (6,), (9,)}
    f: Func = {
        x: (2.5j * character(G, (5,), x) if sub(G, x, (1,)) in K else 0j)
        for x in elements(G)
    }
    result = audit(G, f)
    print(f"|supp f| = {result.space_support}, |supp fhat| = {result.freq_support}")
    print(f"product  = {result.product}, |G| = {result.group_order}")
    print(f"extremal = {result.extremal}")
    print(f"recovered subgroup = {sorted(result.subgroup or [])}")
    print(f"representative = {result.representative}, character = "
          f"{result.character_index}, scalar = {result.scalar:.4g}")

"""Coset recognition by parallelogram closure.

A nonempty subset S of a finite abelian group is the support of some extremal
function for the uncertainty principle if and only if it is a coset of a
subgroup, if and only if it is closed under the parallelogram operation
(x, y, z) -> x - y + z.  The naive test is O(|S|^3); the difference-set test
below is O(|S|^2) and returns the subgroup as a by-product.
"""

from __future__ import annotations

import itertools
from typing import Dict, List, Optional, Set, Tuple

Elem = Tuple[int, ...]
Group = Tuple[int, ...]


def elements(group: Group) -> List[Elem]:
    """All group elements."""
    return [tuple(t) for t in itertools.product(*(range(n) for n in group))]


def add(group: Group, x: Elem, y: Elem) -> Elem:
    """Group addition."""
    return tuple((a + b) % n for a, b, n in zip(x, y, group))


def sub(group: Group, x: Elem, y: Elem) -> Elem:
    """Group subtraction."""
    return tuple((a - b) % n for a, b, n in zip(x, y, group))


def difference_set(group: Group, s: Set[Elem]) -> Set[Elem]:
    """S - S = {x - y : x, y in S}.  Cost O(|S|^2)."""
    return {sub(group, x, y) for x in s for y in s}


def coset_data(group: Group, s: Set[Elem]) -> Optional[Tuple[Set[Elem], Elem]]:
    """Return (K, a) with S = a + K, or None if S is not a coset.

    Correctness: if S = a + K then S - S = K, so |S - S| = |S|.  Conversely
    K := S - S always contains S - a for any a in S, so |S - S| = |S| forces
    S - a = K, and K is a subgroup because it is the difference set of a set
    closed under (x, y, z) -> x - y + z.  Cost O(|S|^2).
    """
    if not s:
        return None
    d = difference_set(group, s)
    if len(d) != len(s):
        return None
    a = sorted(s)[0]
    if {add(group, a, k) for k in d} != s:
        return None
    return d, a


def parallelogram_closed(group: Group, s: Set[Elem]) -> bool:
    """Direct O(|S|^3) test of closure under (x, y, z) -> x - y + z."""
    return bool(s) and all(
        add(group, sub(group, x, y), z) in s for x in s for y in s for z in s
    )


def extremal_supports(group: Group, size: int) -> List[Set[Elem]]:
    """All subsets of the given size that can occur as supports of extremal
    functions -- i.e. all cosets of subgroups of that order."""
    out: List[Set[Elem]] = []
    for combo in itertools.combinations(elements(group), size):
        s = set(combo)
        if coset_data(group, s) is not None:
            out.append(s)
    return out


if __name__ == "__main__":
    G: Group = (4,)
    KLEIN: Group = (2, 2)
    for group, name in [(G, "Z/4"), (KLEIN, "Z/2 x Z/2")]:
        found = extremal_supports(group, 2)
        print(f"{name}: {len(found)} extremal supports of size 2")
        for s in found:
            print(f"   {sorted(s)}")
    print()
    print("non-coset {0,1} in Z/4 :", coset_data(G, {(0,), (1,)}))
    print("coset     {1,3} in Z/4 :", coset_data(G, {(1,), (3,)}))

"""Finite certification of a Poisson summation formula.

A pair (S, T), with S a subset of G and T a set of characters, is a Poisson
pair when

    |G| * sum_{x in S} f(x) = |S| * sum_{psi in T} fhat(psi)

for every test function f.  Because both sides are linear in f and the Dirac
functions span the function space, it suffices to check the |G| identities

    |G| * 1_S(y) = |S| * sum_{psi in T} psi(y),   y in G,

which costs O(|G| |T|) instead of a check over an infinite family.  If they
hold and S is nonempty, then S is a subgroup and T is exactly its annihilator.
"""

from __future__ import annotations

import cmath
import itertools
from typing import List, Optional, Set, Tuple

Elem = Tuple[int, ...]
Group = Tuple[int, ...]

TOL: float = 1e-7


def elements(group: Group) -> List[Elem]:
    """All group elements."""
    return [tuple(t) for t in itertools.product(*(range(n) for n in group))]


def order(group: Group) -> int:
    """The group order."""
    n = 1
    for m in group:
        n *= m
    return n


def add(group: Group, x: Elem, y: Elem) -> Elem:
    """Group addition."""
    return tuple((a + b) % n for a, b, n in zip(x, y, group))


def character(group: Group, k: Elem, x: Elem) -> complex:
    """psi_k(x)."""
    phase = sum(2.0 * cmath.pi * (kj * xj) / nj for kj, xj, nj in zip(k, x, group))
    return cmath.exp(1j * phase)


def dirac_certificate(group: Group, s: Set[Elem], t: Set[Elem]) -> bool:
    """Verify the |G| Dirac identities.  Cost O(|G| |T|)."""
    n = order(group)
    for y in elements(group):
        lhs = n * (1.0 if y in s else 0.0)
        rhs = len(s) * sum(character(group, k, y) for k in t)
        if abs(lhs - rhs) > TOL:
            return False
    return True


def pre_annihilator(group: Group, t: Set[Elem]) -> Set[Elem]:
    """{y in G : psi_k(y) = 1 for all k in T} -- always a subgroup."""
    return {
        y
        for y in elements(group)
        if all(abs(character(group, k, y) - 1.0) < TOL for k in t)
    }


def poisson_structure(
    group: Group, s: Set[Elem], t: Set[Elem]
) -> Optional[Tuple[Set[Elem], Set[Elem]]]:
    """If (S, T) is a Poisson pair, return (subgroup, annihilator) = (S, T);
    otherwise return None.  The subgroup is recomputed independently, as the
    pre-annihilator of T, and checked against S."""
    if not s or not dirac_certificate(group, s, t):
        return None
    h = pre_annihilator(group, t)
    assert h == s, "the rigidity theorem guarantees S is the pre-annihilator of T"
    assert len(s) * len(t) == order(group), "and that |S| |T| = |G|"
    return s, t


if __name__ == "__main__":
    G: Group = (6,)
    subgroup = {(0,), (2,), (4,)}
    annih = {k for k in elements(G) if all(
        abs(character(G, k, x) - 1.0) < TOL for x in subgroup)}
    print("subgroup {0,2,4}, annihilator", sorted(annih))
    print("certified Poisson pair :", poisson_structure(G, subgroup, annih) is not None)
    print("non-subgroup {0,1}     :",
          poisson_structure(G, {(0,), (1,)}, annih) is not None)
    print("coset {1,3,5}          :",
          poisson_structure(G, {(1,), (3,), (5,)}, annih) is not None)

